SELECT region, AVG(tipping_fee) AS avg_tipping_fee
FROM Landfill_All
GROUP BY region;

SELECT facility_name, safety_officer_name, safety_officer_email FROM facilities WHERE facility_id IN (
    SELECT facility_id FROM facilities WHERE facility_name LIKE '%chemical%'
);

SELECT sport, AVG(age) as average_age
FROM athlete_details
GROUP BY sport;

SELECT AVG(water_consumption) AS avg_water_consumption
FROM wastewater_plants
WHERE state_id = 2 AND year BETWEEN 2017 AND 2019;

SELECT SUM(weight) AS total_weight, date
FROM FishBiomass
WHERE farm_id = 2 AND fish_id IN (
    SELECT DISTINCT fish_id FROM FishBiomass WHERE farm_id = 2
)
GROUP BY date;

SELECT gender, SUM(num_screenings) AS total_screenings
FROM cancer_screenings
GROUP BY gender;

SELECT COUNT(CASE WHEN accessible = 1 THEN 1 ELSE NULL END) AS accessible_count,
       COUNT(CASE WHEN accessible = 0 THEN 1 ELSE NULL END) AS non_accessible_count
FROM wheelchair_friendly_fleet;

SELECT DISTINCT user_id FROM user_access WHERE system_accessed IN ('S007', 'S008') AND id IN (
    SELECT id FROM user_access
    GROUP BY user_id
    HAVING COUNT(DISTINCT system_accessed) = 2
);

SELECT MIN(negotiation_start_date) AS earliest_start_date
FROM DefenseProjectTimelines
WHERE country = 'Saudi Arabia';

SELECT country, SUM(co2_emission_kg) AS total_co2_emission
FROM transportation
GROUP BY country;

SELECT id, name, age, 
       DENSE_RANK() OVER (ORDER BY age ASC) as rank_by_age
FROM volunteers;

SELECT AgeGroup, AVG(DonationAmount) AS AverageDonation
FROM DonorAges
GROUP BY AgeGroup;

SELECT COUNT(initiative_id) AS num_initiatives
FROM circular_economy_initiatives
WHERE YEAR(initiative_date) = 2022 AND MONTH(initiative_date) = 1;

SELECT SiteID, COUNT(DISTINCT ObjectType) AS UniqueTypes
FROM Artifact
GROUP BY SiteID;

SELECT COUNT(DISTINCT fan_id) FROM fans WHERE team_id IN (
    SELECT DISTINCT team_id FROM teams WHERE mascot LIKE '%wolf%'
) AND attended = 1;

SELECT SUM(allocation) AS total_allocation
FROM climate_funds
WHERE region = 'Africa' AND initiative_name LIKE '%Adaptation%' AND funding_year = 2020;

SELECT AVG(Water_Consumption) AS Average_Water_Consumption
FROM Household_Water_Usage
WHERE City = 'Mumbai' AND Year IN (2018, 2019);

SELECT AVG(budget) AS avg_budget
FROM agricultural_innovation
WHERE region IN ('region_1', 'region_2');

SELECT AVG(rating) AS avg_rating, state
FROM Residential_Buildings
GROUP BY state;

SELECT id, incident_name, country, incident_category 
FROM eu_ai_safety_incidents 
WHERE country IN ('Germany', 'France', 'UK') AND (incident_category = 'Data Privacy' OR incident_category = 'Unintended Behavior');

SELECT region, AVG(assets_value) AS avg_assets_value
FROM customers
GROUP BY region;

SELECT vessel_id, SUM(cargo_weight) AS total_cargo_weight
FROM vessel_cargo
GROUP BY vessel_id;

SELECT SUM(steps) AS total_steps
FROM DailySteps
WHERE activity_date BETWEEN '2021-01-01' AND '2021-01-31';

SELECT AVG(co2_emission) AS avg_co2_emission
FROM public_buses
WHERE city IN ('Los Angeles', 'London');

SELECT SUM(viewers) 
FROM TV_Shows 
WHERE region = 'Canada' AND year = 2022 AND rating > 8.5;

SELECT SUM(income) AS total_income
FROM clients
WHERE country = 'Canada' AND is_socially_responsible_investor = true;

SELECT d.name, COUNT(e.id) AS employee_count
FROM department d
JOIN (
    SELECT id FROM department WHERE name = 'Mining'
) m ON d.id = m.id
GROUP BY d.name;

SELECT country, SUM(incidents) AS total_incidents
FROM Ingredient_Sourcing
GROUP BY country;

SELECT team, SUM(engagement) AS total_engagement
FROM social_media
GROUP BY team;

SELECT location, SUM(count) AS total_count
FROM co_ownership_location_count
GROUP BY location;

SELECT SUM(ingredients.cost) FROM ingredients JOIN (
    SELECT dish_id FROM ingredients WHERE is_gluten_free = true AND dish_id IN (
        SELECT dish_id FROM ingredients WHERE name LIKE '%healthy%'
    )
) AS gluten_free_dishes ON ingredients.dish_id = gluten_free_dishes.dish_id;

SELECT AVG(v.age) AS avg_age
FROM volunteers v
WHERE v.sessions_completed > 5;

SELECT AVG(depth), region
FROM marine_protected_areas
GROUP BY region;

SELECT AVG(funding_amount) AS avg_funding FROM funding 
WHERE company_name IN (
    SELECT company_name FROM company_founding 
    WHERE foundation_year >= YEAR(CURDATE()) - INTERVAL 10 YEAR
);

SELECT article_language, COUNT(*) AS article_count
FROM articles
GROUP BY article_language;

SELECT type, AVG(temperature) AS avg_temperature
FROM crop
GROUP BY type;

SELECT SUM(funding.amount) AS total_funding FROM founders 
JOIN funding ON founders.company_id = funding.company_id 
WHERE founders.gender = 'female';

SELECT AVG(age) AS avg_age
FROM policyholders
WHERE state = 'CA' AND policy_type = 'home';

SELECT SUM(precipitation) AS total_precipitation
FROM precipitation
WHERE sensor_id = 005 AND strftime('%Y-%m', timestamp) = '2022-01';

SELECT judge_name, COUNT(*) AS num_cases
FROM criminal_cases
GROUP BY judge_name;

SELECT ocean_basin, MIN(temperature) AS min_temp
FROM ocean_temperature
GROUP BY ocean_basin;

SELECT id, name, scheduled_completion_date, actual_completion_date
FROM Project
WHERE actual_completion_date < scheduled_completion_date;

SELECT AVG(safety_score) AS avg_safety_score
FROM creative_ai
WHERE country IN ('France', 'Germany', 'Spain');

SELECT date, SUM(revenue) AS total_revenue
FROM daily_revenue
GROUP BY date;

SELECT State, SUM(PermitCount) AS TotalPermits
FROM PermitsByState
GROUP BY State;

SELECT SUM(amount) AS total_funding
FROM Funding
WHERE program IN ('Women in Art', 'Non-Binary Dance Troupe', 'Female Composers Initiative');

SELECT RegionName, SUM(Biomass) AS TotalBiomass
FROM FarmingRegions
GROUP BY RegionName;

SELECT AVG(capacity), country
FROM projects
GROUP BY country;

SELECT SUM(CASE WHEN is_electric = 1 THEN 1 ELSE 0 END) AS electric_count,
       SUM(CASE WHEN is_hybrid = 1 THEN 1 ELSE 0 END) AS hybrid_count
FROM vehicle_data;

SELECT COUNT(evaluation_id) AS total_evaluations
FROM evaluations
WHERE YEAR(evaluation_date) IN (2020, 2021);

SELECT MIN(price / grams) AS min_price_per_gram
FROM inventory
WHERE state = 'Nevada' AND year = 2022 AND strain = 'Gelato';

SELECT DrugName, ApprovalDate, ApprovalYear,
       DENSE_RANK() OVER (ORDER BY ApprovalDate) AS Rank
FROM MarketAccess;

SELECT SUM(quantity) 
FROM lanthanum_imports 
WHERE year IN (2018, 2019) AND (country = 'Norway' OR country = 'Sweden');

SELECT MAX(depth), MIN(depth)
FROM ocean_depths
WHERE ocean = 'Arctic Ocean';

SELECT AVG(consumer_rating) AS average_consumer_rating
FROM product_info
WHERE is_cruelty_free = true AND source_country = 'IN';

SELECT state, COUNT(*) AS num_schools
FROM schools
GROUP BY state;

SELECT factory_id, COUNT(DISTINCT worker_id) AS total_workers
FROM workers
GROUP BY factory_id;

SELECT country, population FROM (
    SELECT country, population,
           ROW_NUMBER() OVER (ORDER BY population DESC) as rn
    FROM countries
) subquery
WHERE rn <= 2;

SELECT SUM(medical_issues) AS total_medical_issues FROM Medical_Records WHERE astronaut_id IN (
    SELECT astronaut_id FROM Astronauts WHERE gender = 'female'
);

SELECT AVG(labor_cost) AS avg_labor_cost
FROM factories
WHERE country IN ('Kenya', 'Nigeria', 'South Africa');

SELECT COUNT(id) AS num_studies
FROM genetic_research
WHERE location = 'United Kingdom' AND STRFTIME('%Y', start_date) = '2019';

SELECT industry, SUM(application_count) AS total_apps
FROM creative_ai_applications
GROUP BY industry;

SELECT COUNT(*) AS count_of_endangered_species
FROM marine_mammals
WHERE conservation_status = 'Endangered';

SELECT COUNT(id) AS count_of_shariah_compliant_financial_institutions
FROM financial_institutions
WHERE country IN ('Middle East', 'North Africa') AND is_shariah_compliant = true;

SELECT MIN(v.sessions_completed) AS min_sessions_completed
FROM volunteers v
WHERE v.age > 30;

SELECT AVG(rating) AS avg_rating
FROM projects
WHERE location = 'Germany';

SELECT gender, AVG(mental_health_score) AS avg_mh_score
FROM students
GROUP BY gender;

SELECT COUNT(*), SUM(trip_duration) AS total_trip_duration
FROM multimodal_trips_canada
WHERE city = 'Toronto' AND mode = 'public';

SELECT t.name, COUNT(*) AS victories
FROM teams t
GROUP BY t.id;

SELECT ingredient_id, name FROM ingredients WHERE ingredient_id IN (
    SELECT ingredient_id FROM ingredients
    JOIN country_biodiversity ON ingredients.sourcing_country = country_biodiversity.country
    WHERE country_biodiversity.biodiversity_index > 75
);

SELECT AVG(Salary) AS AverageSalary
FROM Employees
WHERE Ethnicity = 'Latinx' AND Department = 'Engineering';

SELECT AVG(severity) AS avg_severity
FROM vulnerabilities
WHERE category = 'Malware';

SELECT event_type, SUM(CASE WHEN year = 2018 THEN 1 ELSE 0 END) AS count_2018, SUM(CASE WHEN year = 2019 THEN 1 ELSE 0 END) AS count_2019
FROM defense_diplomacy
GROUP BY event_type;

SELECT SUM(CASE WHEN T2.filed_country IN ('Mexico', 'Argentina', 'Colombia') THEN 1 ELSE 0 END) AS total_ethical_patents
FROM patents AS T1
JOIN (
    SELECT DISTINCT filed_country FROM patents WHERE ethical = true
) AS T2 ON T1.filed_country = T2.filed_country;

SELECT MIN(property_tax) AS min_property_tax
FROM buildings
WHERE city = 'Vancouver' AND num_bedrooms > 3;
